function header(){return `<header class="top q-header"><div class="brand q-header-brand" data-action="home" role="button" tabindex="0" aria-label="قبس — الرجوع للرئيسية"><div class="brand-icon q-logo-mark">${logo()}</div><div class="q-brand-copy"><strong>قبس</strong><small>QABAS</small></div><span class="q-brand-divider" aria-hidden="true"></span><span class="q-brand-descriptor">تحدّي المعرفة</span></div><div class="top-actions"><span class="q-header-ornament" aria-hidden="true">✦</span></div></header>`}
function home(){return `${header()}<section class="hero"><div class="arch"><div class="hero-emoji">✦</div></div><span class="q-eyebrow">QABAS · KNOWLEDGE & CHALLENGE</span><h1>شلة أصحاب وتحدّي جامد!</h1><p>اختاروا لعبة، لمّوا الشلة، وشوفوا مين هيكسب!</p><div class="hero-actions"><button class="btn" data-action="setup">🏆 ابدأ مسابقة</button><button class="btn secondary" data-action="free">🎮 اللعب الحر</button>${session?`<button class="btn subtle" data-action="continue">↶ استكمال جلستك</button>`:''}</div></section><h2 class="section-title">ألعاب قبس <small>اختاروا اللي يعجبكم</small></h2><section class="game-grid q-home-games">${GAMES.map((x,i)=>`<button class="tile q-tile" data-action="quick" data-id="${x[0]}"><span class="q-number">0${i+1}</span><span class="emoji q-framed-icon">${x[2]}</span><strong>${x[1]}</strong><small>${x[3]}</small></button>`).join('')}</section><section class="q-note">✦ كل الأسئلة مصممة للتعلم والمتعة. المعلومة موثقة، والإجابة بتظهر بعد ما تجاوبوا.</section>${footer()}`}
function footer(){return `<footer class="footer">قبس | Qabas · المعرفة تجمعنا<br>نسخة أولية تجريبية — ${ACTIVE_Q.length} سؤالًا مبدئيًا؛ بنك الـ600 سؤال قيد الإعداد والمراجعة.</footer>`}
function setup(){const f=setupKind==='free';return `${header()}<main class="screen"><div class="step-head"><div><span class="q-eyebrow">${f?'اللعب الحر':'المسابقة الشاملة'}</span><h2>${f?'اختار لعبتك':'جهّز المسابقة'}</h2>${f?'<p>اختار اللعبة وعدد الأسئلة، ويلا نبدأ!</p>':''}</div></div><div class="panel q-setup"><div class="q-intro"><span>${f?'🎮':'🏆'}</span><div><strong>${f?'جاهز تلعب؟':'جاهزين للتحدي؟'}</strong>${f?'':'<p>أكتر من لعبة، ونقاط تحدد الفائز</p>'}</div></div>${`<div class="field q-select-games ${f?'':'q-tournament-games'}"><label>اختار اللعبة ${!f?`<small class="q-count">(${config.games.length} مختارة)</small>`:""}</label><div class="q-game-grid">${(f?GAMES:TOURNAMENT_GAMES).map(g=>{const chosen=f?freeType===g[0]:config.games.includes(g[0]);return `<button type="button" class="q-game-card ${chosen?"active":""}" aria-pressed="${chosen}" data-action="${f?"free-game":"toggle-game"}" data-id="${g[0]}"><span class="q-game-icon">${g[2]}</span><span class="q-game-meta"><strong>${g[1]}</strong><small>${g[3]}</small></span><span class="q-game-check">✓</span></button>`}).join("")}</div></div>`}${!f?`<div class="field"><label>مين هيلعب؟</label><div class="seg"><button data-action="mode" data-id="individual" class="${config.mode==='individual'?'active':''}">أفراد</button><button data-action="mode" data-id="teams" class="${config.mode==='teams'?'active':''}">فرق</button></div></div><div class="field"><label>يلا نكتب أسماء ${config.mode==='teams'?'الفرق':'اللاعبين'}</label><div class="players">${config.players.map((p,i)=>`<div class="player-row"><input data-player="${i}" maxlength="30" value="${escapeHtml(p)}" aria-label="اسم المشارك ${i+1}">${config.players.length>2?`<button data-action="delete-player" data-id="${i}" title="حذف">✕</button>`:''}</div>`).join('')}</div><button class="btn subtle" data-action="add-player">+ إضافة ${config.mode==='teams'?'فريق':'لاعب'}</button></div>`:''}<div class="field"><label>عدد الأسئلة ${f?'في الجولة':'لكل لاعب أو فريق'}</label><select id="rounds">${[2,3,5,10].map(n=>`<option value="${n}" ${config.rounds===n?'selected':''}>${n} أسئلة</option>`).join('')}</select></div><details class="q-details"><summary>صعوبة الأسئلة <small id="current-level">${['','سهل','متوسط','صعب'][config.level]}</small></summary><div class="chip-grid q-levels">${[[1,'سهل'],[2,'متوسط'],[3,'صعب']].map(x=>`<button type="button" class="chip ${config.level===x[0]?'active':''}" data-action="set-level" data-id="${x[0]}">${x[1]}</button>`).join('')}</div></details><div class="setup-actions"><button class="btn" data-action="begin">ابدأ اللعب</button></div></div></main>${footer()}`}
function free(){return `${header()}<main class="screen"><div class="step-head"><div><span class="q-eyebrow">FREE PLAY</span><h2>اللعب الحر</h2><p>اختار اللعبة وبعدها اضبط إعدادات بسيطة.</p></div><button class="icon-btn" data-action="home">✕</button></div><section class="game-grid">${GAMES.map((g,i)=>`<button class="tile q-tile" data-action="quick" data-id="${g[0]}"><span class="q-number">0${i+1}</span><span class="emoji q-framed-icon">${g[2]}</span><strong>${g[1]}</strong><small>${g[3]}</small></button>`).join('')}</section></main>${footer()}`}
function current(){return session?.queue?.[session.index]||null}
function shuffled(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function pool(level=0){let p=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&(level===0||q.level===level));return shuffled(p)}
function buildQueue(){multiEnabled=setupKind==='tournament';config.games=config.games.filter(id=>(multiEnabled?TOURNAMENT_GAMES:GAMES).some(g=>g[0]===id));if(!config.games.length)return [];const turns=[];let used=new Set(),total=(multiEnabled?config.players.length:1)*config.rounds;for(let i=0;i<total;i++){let game=config.games[i%config.games.length];let level=config.level||(game==='risk'?i%3+1:0);let options=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&(level===0||q.level===level)&&!used.has(q.id));if(game==='guess'){options=options.filter(q=>Array.isArray(hints[q.id])&&hints[q.id].length===3);if(!options.length)break;}if(!options.length)options=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&!used.has(q.id));if(!options.length)break;let q=shuffled(options)[0];used.add(q.id);turns.push({q:q.id,game,player:i%(multiEnabled?config.players.length:1),golden:false});}if(turns.length&&multiEnabled&&setupKind==='tournament'){let options=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&!used.has(q.id));if(options.length)turns.push({q:shuffled(options)[0].id,game:'steal',player:0,golden:true});}return turns;}
function save(){if(session){try{localStorage.setItem(storeKey,JSON.stringify(session))}catch(e){notify('تعذر حفظ الجلسة على هذا المتصفح')}}}
function load(){try{let s=JSON.parse(localStorage.getItem(storeKey)||'null');if(!s||!Array.isArray(s.players)||!Array.isArray(s.queue)||!Array.isArray(s.scores)||s.players.length!==s.scores.length||!Number.isInteger(s.index)||s.index<0||s.index>s.queue.length||!s.queue.every(t=>t&&typeof t.q==='string'&&typeof t.game==='string'&&Number.isInteger(t.player)&&t.player>=0&&t.player<s.players.length&&lookup(t.q)))return null;if(typeof s.multiplayer!=='boolean')s.multiplayer=true;if(s.index===s.queue.length)s.finished=true;return s}catch(e){return null}}
function initSession(queue,players){session={multiplayer:multiEnabled,kind:setupKind,players,queue,index:0,scores:players.map(()=>0),answered:false,revealed:false,picked:-1,clues:1,selectedLevel:0,remaining:60,running:false,speedCorrect:0,speedWrong:0,speedTotal:0,claimed:0,freeResults:[],freeTurnRecorded:false,finished:false,usedIds:queue.map(t=>t.q)};save();view='play';render()}
function lookup(id){return ACTIVE_Q.find(q=>q.id===id)}
function getChoices(q){const arr=[q.answer,...(DISTRACT[q.id]||EXTRA_DISTRACT[q.id]||[])];let rotation=q.id.charCodeAt(q.id.length-1)%4;return [...arr.slice(rotation),...arr.slice(0,rotation)]}
function getGame(g){return GAMES.find(x=>x[0]===g)||(g==='risk'?['risk','اختار مستوى التحدي','💎','اختر الصعوبة والنقاط']:GAMES[0])}
function getTopic(t){return TOPICS.find(x=>x[0]===t)||TOPICS[0]}
function freeSummary(){
const results=Array.isArray(session.freeResults)?session.freeResults:[];
const right=results.filter(x=>x.correct).length;
const total=results.length;
const percent=total?Math.round(right/total*100):0;
const perfect=total>0&&right===total;
const mostlyRight=total>0&&right>total/2;
const message=perfect?{icon:'🏆',title:'أداء استثنائي!',subtitle:'ما شاء الله! كل إجاباتك صحيحة. تفوّق رائع، استمر في التألق!'}:mostlyRight?{icon:'🌟',title:'أحسنت!',subtitle:'إجاباتك الصحيحة هي الأغلبية. شغل ممتاز، وخلّي الجولة القادمة أقوى!'}:{icon:'🌱',title:'حاول مرة أخرى!',subtitle:'كل سؤال فرصة تتعلم منها. راجع الإجابات وارجع تحدّى نفسك من جديد!'};
const review=results.map((r,i)=>{const q=lookup(r.q);if(!q)return '';return `<div class="q-free-review-item"><span class="q-free-review-status ${r.correct?'is-correct':'is-wrong'}">${r.correct?'✓ صحيحة':'✕ غير صحيحة'}</span><div class="q-free-review-text"><strong>${i+1}. ${escapeHtml(q.text)}</strong><p>الإجابة الصحيحة: <b>${escapeHtml(q.answer)}</b></p>${r.choice&&!r.correct?`<small>إجابتك: ${escapeHtml(r.choice)}</small>`:''}</div></div>`}).join('');
return `${header()}<main class="screen q-free-results"><section class="panel q-finish q-free-finish" aria-label="نتيجة اللعب الحر"><div class="q-free-medal" aria-hidden="true">${message.icon}</div><span class="q-eyebrow">✦ نتيجة اللعب الحر ✦</span><h1>${message.title}</h1><p class="q-free-subtitle">${message.subtitle}</p><div class="q-free-score"><strong>${right} / ${total}</strong><span>إجابات صحيحة · ${percent}٪</span></div><div class="q-free-progress"><span style="width:${percent}%"></span></div><div class="setup-actions"><button class="btn" data-action="free-retry">حاول جولة جديدة</button><button class="btn secondary" data-action="free">لعبة أخرى</button><button class="btn subtle" data-action="home">الرئيسية</button></div></section><section class="panel q-free-review"><h2>📖 مراجعة الإجابات</h2><p>راجع كل سؤال وإجابته الصحيحة عشان تستفيد من الجولة.</p>${review||'<p>لم تُسجَّل إجابات في هذه الجولة.</p>'}</section></main>${footer()}`;
}
function markFree(correct,choice='',questionId=null){if(!session||session.multiplayer)return;if(!Array.isArray(session.freeResults))session.freeResults=[];if(questionId===null){if(session.freeTurnRecorded)return;questionId=current()?.q;session.freeTurnRecorded=true;}if(questionId)session.freeResults.push({q:questionId,correct:Boolean(correct),choice:String(choice||'')});save()}
function board(){
if(!session.multiplayer)return freeSummary();
const finished=Boolean(session.finished);
const best=Math.max(...session.scores);
const winners=session.players.filter((_,i)=>session.scores[i]===best);
const tied=winners.length>1;
const title=tied?'تعادل!':'مبروك للفائز!';
const names=winners.map(n=>escapeHtml(n)).join(' <span class="q-winner-join">و</span> ');
const celebration=finished?`<section class="q-victory" aria-label="${tied?'تعادل في المسابقة':'الاحتفال بالفائز'}"><div class="q-confetti" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="--i:${i};--delay:${(i%7)*-0.24}s"></i>`).join('')}</div><div class="q-victory-content"><div class="q-victory-kicker">✦ انتهت المسابقة ✦</div><div class="q-victory-trophy" aria-hidden="true">${tied?'🤝':'🏆'}</div><h1 class="q-victory-title">${title}</h1><div class="q-winner-name" aria-live="polite">${names}</div><p class="q-victory-message">${tied?'المركز الأول متعادل! يلا سؤال فاصل ونحسمها.':'تستاهل الفوز! كانت مسابقة حماسية.'}</p><div class="q-victory-score">${best} نقطة</div></div></section>`:'';
return `${header()}<main class="screen q-results-screen">${celebration}<div class="panel q-results-panel"><div class="step-head"><div><h2>🏅 ${finished?'الترتيب النهائي':'لوحة النتائج'}</h2><p>${finished?'نتيجة كل لاعب أو فريق':'الترتيب الحالي'}</p></div>${finished?'':'<button class="icon-btn" data-action="continue" title="رجوع للعب">✕</button>'}</div>${scoreboard()}${finished?`<div class="setup-actions"><button class="btn" data-action="setup">مسابقة جديدة</button>${tied?'<button class="btn secondary" data-action="tie">سؤال فاصل ⚡</button>':'<button class="btn secondary" data-action="home">الرئيسية</button>'}</div>`:`<p class="hint">تقدر تراجع النقاط وتكمل اللعب. لو اتسجلت نقطة بالغلط، عدّلها من أزرار ±.</p><div class="setup-actions"><button class="btn" data-action="continue">استكمال اللعب</button><button class="btn secondary" data-action="home">الرئيسية</button></div>`}</div></main>${footer()}`;
}
function scoreboard(){let items=session.players.map((name,i)=>({name,score:session.scores[i],i})).sort((a,b)=>b.score-a.score);return `<div class="scoreboard">${items.map((p,n)=>`<div class="score-row"><div><span>${['🥇','🥈','🥉'][n]||'◈'}</span> <strong>${escapeHtml(p.name)}</strong></div><div style="display:flex;align-items:center;gap:8px">${session.finished?"":`<button class="icon-btn" style="min-width:29px;width:30px;height:30px;padding:2px" data-action="score-minus" data-id="${p.i}" aria-label="إنقاص نقاط ${escapeHtml(p.name)}">−</button>`}<b>${p.score} نقطة</b>${session.finished?"":`<button class="icon-btn" style="min-width:29px;width:30px;height:30px;padding:2px" data-action="score-plus" data-id="${p.i}" aria-label="زيادة نقاط ${escapeHtml(p.name)}">+</button>`}</div></div>`).join('')}</div>`}
function sourceBlock(q){return q.explain?`<p class="q-explain">${escapeHtml(q.explain)}</p>`:''}
function questionCard(q,label){return `<div class="question-card"><small>${escapeHtml(label||getTopic(q.topic)[1])}</small><h2>${escapeHtml(q.text)}</h2></div>`}
function reveal(q){return `<div class="reveal"><h3>✅ الإجابة: ${escapeHtml(q.answer)}</h3>${sourceBlock(q)}</div>`}
function scoreActions(defaultPoints=10,showClaim=false){if(!session.multiplayer)return `<div class="control-row"><button class="btn" data-action="free-mark" data-id="yes">✅ إجابتي صحيحة</button><button class="btn secondary" data-action="free-mark" data-id="no">✕ إجابتي غير صحيحة</button></div>`;let choice=showClaim?session.claimed:current().player;return `<div class="field"><label>تسجيل الإجابة لـ</label><select id="claim-player">${session.players.map((x,i)=>`<option value="${i}" ${i===choice?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></div><div class="control-row"><button class="btn" data-action="award" data-points="${defaultPoints}">✅ صحيحة (+${defaultPoints})</button><button class="btn secondary" data-action="award" data-points="0">✕ غير صحيحة / تخطي</button></div>`}
function gamePlay(){let turn=current();if(!turn){session.finished=true;save();view='board';return board()}let q=lookup(turn.q);if(!q){return `<p>تعذر تحميل السؤال</p>`}let game=getGame(turn.game),player=session.players[turn.player],label=getTopic(q.topic)[1];let progress=Math.round(100*session.index/session.queue.length);let html=`${header()}<main class="screen"><div class="game-head">${session.multiplayer?'<button class="icon-btn" data-action="board" title="لوحة النتائج">🏆</button>':''}<span class="pill">${game[2]} ${game[1]}</span><span class="pill">${session.index+1} / ${session.queue.length}</span></div><div class="progress"><span style="width:${progress}%"></span></div>${turn.golden?'<div class="golden">✦ الجولة الذهبية — 40 نقطة للفائز ✦</div>':''}<div class="turn"><div>${session.multiplayer?`دور: <strong>${turn.golden?'جميع اللاعبين':escapeHtml(player)}</strong> · `:''}<small>${label}</small></div><button class="btn subtle" style="min-height:39px;padding:6px 13px" data-action="skip">تخطي السؤال</button></div>`;
if(turn.game==='quiz'){let arr=getChoices(q);html+=questionCard(q,label)+`<div class="answers">${arr.map((a,i)=>`<button class="answer ${session.answered?(a===q.answer?'correct':session.picked===i?'wrong':''):''}" data-action="choose" data-id="${i}" ${session.answered?'disabled':''}><b>${'أبجد'[i]}</b><span>${escapeHtml(a)}</span></button>`).join('')}</div>${session.answered?`${reveal(q)}<div class="control-row"><button class="btn" data-action="next">السؤال التالي ←</button></div>`:''}`}
else if(turn.game==='guess'){let clues=hints[q.id]||['التلميحات مش متاحة للسؤال ده','جرّبوا سؤال تاني','التلميحات مش متاحة'];;html+=`<div class="question-card"><small>من أنا؟ — اقرأ التلميحات بصوت عالٍ</small><h2>${escapeHtml(clues[session.clues-1])}</h2></div><p class="mini-help" style="text-align:center">التلميح ${session.clues} من 3${session.multiplayer?` · نقاط الإجابة: ${[30,20,10][session.clues-1]}`:''}</p>${session.revealed?`${reveal(q)}${scoreActions([30,20,10][session.clues-1])}`:`<div class="control-row">${session.clues<3?'<button class="btn secondary" data-action="hint">تلميح إضافي</button>':''}<button class="btn" data-action="reveal">كشف الإجابة</button></div>`}`}
else if(turn.game==='speed'){html+=`<div class="timer" aria-live="off">${String(Math.floor(session.remaining/60)).padStart(2,'0')}:${String(session.remaining%60).padStart(2,'0')}</div><div class="mini-help" style="text-align:center">إجابات صحيحة: ${session.speedCorrect} · أخطاء/تخطي: ${session.speedWrong}${session.multiplayer?' · كل إجابة صحيحة = 10 نقاط':''}</div>${questionCard(q,label)}${session.revealed?reveal(q):'<p class="mini-help" style="text-align:center">اقرأ السؤال، ثم اكشف الإجابة للتحقق.</p>'}<div class="control-row">${!session.revealed?`<button class="btn secondary" data-action="reveal">كشف الإجابة</button>`:`<button class="btn" data-action="speed-mark" data-points="10">${session.multiplayer?'✅ صح +10':'✅ صح'}</button><button class="btn secondary" data-action="speed-mark" data-points="0">✕ تخطي/غلط</button>`}<button class="btn subtle" data-action="speed-toggle">${session.running?'⏸ إيقاف مؤقت':'▶️ بدء / استئناف'}</button></div><p class="hint" style="text-align:center">ينتهي الدور بعد 60 ثانية أو يمكنك إنهاؤه يدويًا. في هذا الوضع تُضاف الأسئلة المتتابعة من المكتبة دون تكرار داخل الجلسة قدر الإمكان.</p><div class="control-row"><button class="btn secondary" data-action="speed-end">إنهاء جولة الدقيقة</button></div>`}
else if(turn.game==='risk'){if(!session.selectedLevel){html+=`<div class="question-card"><small>المخاطرة والجوائز</small><h2>اختر مستوى التحدي</h2></div><div class="game-select">${[[1,'سهل · 10 نقاط'],[2,'متوسط · 20 نقطة'],[3,'صعب · 30 نقطة']].map(x=>`<button data-action="select-level" data-id="${x[0]}">${x[1]}</button>`).join('')}</div>`}else{let p=[0,10,20,30][session.selectedLevel];html+=questionCard(q,`مستوى ${['','سهل','متوسط','صعب'][session.selectedLevel]} · ${p} نقطة`)+`${session.revealed?`${reveal(q)}${scoreActions(p)}`:`<div class="control-row"><button class="btn" data-action="reveal">كشف الإجابة</button></div>`}`}}
else if(turn.game==='flash'){html+=`<div class="question-card flash" data-action="reveal" role="button" tabindex="0"><small>🃏 بطاقة معرفية — اضغط لقلب البطاقة</small><h2>${session.revealed?escapeHtml(q.answer):escapeHtml(q.text)}</h2><small>${session.revealed?'الإجابة ظهرت':'جاوبوا بصوت عالٍ ثم اقلبوا البطاقة'}</small></div>${session.revealed?`${reveal(q)}${scoreActions(10)}`:`<div class="control-row"><button class="btn" data-action="reveal">اقلب البطاقة ←</button></div>`}`}
else {html+=questionCard(q,label)+`<p class="mini-help" style="text-align:center">${session.multiplayer?'أول واحد يعرف الإجابة يقولها! ولو غلط، الفرصة لغيره.':'جاوب الأول وبعدين اكشف الإجابة.'}</p>${session.revealed?`${reveal(q)}${scoreActions(turn.golden?40:20,true)}`:`<div class="control-row"><button class="btn" data-action="reveal">كشف الإجابة</button></div>`}`}
html+=`</main>${footer()}`;return html}
function notify(s){let e=$('#toast');e.textContent=s;e.classList.remove('hide');clearTimeout(notify.t);notify.t=setTimeout(()=>e.classList.add('hide'),2600)}
function clearClock(){if(clockId!==null){clearInterval(clockId);clockId=null}}
function tick(){if(!session||view!=='play'||!session.running||current()?.game!=='speed'){clearClock();return}session.remaining=Math.max(0,session.remaining-1);if(session.remaining===0){session.running=false;clearClock();notify('انتهت الدقيقة! أنهِ الجولة لتثبيت النتيجة.')}save();render()}
function startClock(){clearClock();if(session?.running)clockId=setInterval(tick,1000)}
function next(){if(!session.multiplayer&&!session.freeTurnRecorded){markFree(false)}clearClock();session.running=false;session.index++;session.freeTurnRecorded=false;session.answered=false;session.picked=-1;session.revealed=false;session.clues=1;session.selectedLevel=0;session.remaining=60;session.speedCorrect=0;session.speedWrong=0;session.speedTotal=0;session.claimed=0;if(session.index>=session.queue.length){session.finished=true;view='board'}save();render()}
function record(points){let idx=Number($('#claim-player')?.value??current().player);if(!Number.isInteger(idx)||idx<0||idx>=session.players.length)return;session.scores[idx]+=points;next()}
function persistUI(){try{const isSetup=view==='setup';const openSections=isSetup?[...document.querySelectorAll('.q-setup details')].map((d,i)=>d.open?i:-1).filter(i=>i>=0):[];localStorage.setItem(uiStoreKey,JSON.stringify({view,config,setupKind,multiEnabled,freeType,openSections,scrollY:window.scrollY||0}))}catch(e){}}
function restoreUI(){try{const state=JSON.parse(localStorage.getItem(uiStoreKey)||'null');if(!state||!['home','setup','play','board'].includes(state.view))return null;if(state.config&&Array.isArray(state.config.players)&&Array.isArray(state.config.games)){config={...config,...state.config,topics:TOPICS.map(t=>t[0])};config.games=config.games.filter(g=>GAMES.some(x=>x[0]===g));if(!config.games.length)config.games=GAMES.map(g=>g[0]);}
if(state.setupKind==='free'||state.setupKind==='tournament')setupKind=state.setupKind;
multiEnabled=setupKind==='tournament';
if(multiEnabled){config.games=config.games.filter(id=>TOURNAMENT_GAMES.some(g=>g[0]===id));if(!config.games.length)config.games=TOURNAMENT_GAMES.map(g=>g[0])}
if(GAMES.some(g=>g[0]===state.freeType))freeType=state.freeType;
if(['play','board'].includes(state.view)&&!session)return null;
if(state.view==='play'&&session?.finished)return {...state,view:'board'};
return state;}catch(e){return null}}
function render(options={}){try{return renderSafe(options)}catch(error){console.error('Qabas render recovery:',error);clearClock();view='home';session=null;const root=$('#app');if(root){root.innerHTML=home();}persistUI()}}
function renderSafe(options={}){const previousSetup=view==='setup'&&Boolean(document.querySelector('.q-setup'));const openSections=previousSetup?[...document.querySelectorAll('.q-setup details')].map((d,i)=>d.open?i:-1).filter(i=>i>=0):[];const y=window.scrollY||0;let root=$('#app');root.innerHTML=view==='home'?home():view==='setup'?setup():view==='free'?free():view==='board'&&session?board():view==='play'&&session?gamePlay():home();if(view==='setup'&&previousSetup){document.querySelectorAll('.q-setup details').forEach((d,i)=>{d.open=openSections.includes(i)})}if(view==='play'&&session?.running&&current()?.game==='speed'&&clockId===null)startClock();if(options.preserveScroll)window.scrollTo(0,y);else if(options.restoreScroll)window.scrollTo(0,options.scrollY||0);else window.scrollTo(0,0);persistUI()}
function syncSetup(){document.querySelectorAll('[data-player]').forEach(x=>{config.players[Number(x.dataset.player)]=x.value.trim()});config.rounds=Number($('#rounds')?.value||config.rounds);config.level=Number($('#level')?.value??config.level)}
function changeTopic(id){config.topics=config.topics.includes(id)?config.topics.filter(x=>x!==id):[...config.topics,id]}
function addSpeedQuestion(){let used=new Set(session.usedIds);let possibilities=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&!used.has(q.id));if(!possibilities.length)return false;let pick=shuffled(possibilities)[0];session.usedIds.push(pick.id);session.queue[session.index].q=pick.id;session.revealed=false;save();return true}
function launchFree(game){if(!GAMES.some(g=>g[0]===game))game=GAMES[0][0];clearClock();freeType=game;setupKind='free';multiEnabled=false;config.mode='individual';config.players=[''];config.games=[game];config.topics=TOPICS.map(x=>x[0]);config.rounds=5;config.level=0;view='setup';render()}
function act(action,id,el){if(action==='home'){clearClock();if(session)session.running=false;save();view='home';return render()}
if(action==='setup'){clearClock();if(session)session.running=false;save();setupKind='tournament';multiEnabled=true;config.games=TOURNAMENT_GAMES.map(x=>x[0]);config.players=['اللاعب 1','اللاعب 2'];view='setup';return render()}
if(action==='free'){return launchFree(freeType)}
if(action==='free-game'){syncSetup();freeType=id;config.games=[id];document.querySelectorAll('[data-action="free-game"]').forEach(b=>{b.classList.toggle('active',b.dataset.id===id);b.setAttribute('aria-pressed',String(b.dataset.id===id))});persistUI();return}
if(action==='multi'){syncSetup();multiEnabled=id==='group';if(multiEnabled&&config.players.length<2)config.players=['اللاعب 1','اللاعب 2'];return render({preserveScroll:true})}
if(action==='quick')return launchFree(id);
if(action==='set-level'){config.level=Number(id);el.closest('details').open=false;let chosen=document.querySelector('#current-level');if(chosen)chosen.textContent=['','سهل','متوسط','صعب'][config.level];persistUI();return}
if(action==='continue'){view='play';session.finished?view='board':null;return render()}
if(action==='board'){if(session){clearClock();session.running=false;save();view='board';render()}return}
if(action==='mode'){syncSetup();config.mode=id;config.players=id==='teams'?['الفريق الأول','الفريق الثاني']:['اللاعب 1','اللاعب 2'];return render({preserveScroll:true})}
if(action==='toggle-game'){if(!TOURNAMENT_GAMES.some(g=>g[0]===id))return;syncSetup();config.games=config.games.includes(id)?config.games.filter(x=>x!==id):[...config.games,id];el.classList.toggle('active',config.games.includes(id));el.setAttribute('aria-pressed',String(config.games.includes(id)));let count=el.closest('.q-select-games')?.querySelector('.q-count');if(count)count.textContent=`(${config.games.length} مختارة)`;persistUI();return}
if(action==='toggle-topic'){syncSetup();changeTopic(id);el.classList.toggle('active',config.topics.includes(id));el.setAttribute('aria-pressed',String(config.topics.includes(id)));let count=el.closest('details')?.querySelector('.q-count');if(count)count.textContent=`(${config.topics.length} مختارة)`;return}
if(action==='add-player'){syncSetup();if(config.players.length>=12)return notify('ينفع لحد 12 لاعب أو فريق');config.players.push(`${config.mode==='teams'?'الفريق':'اللاعب'} ${config.players.length+1}`);return render({preserveScroll:true})}
if(action==='delete-player'){syncSetup();if(config.players.length<=2)return notify('خلي معانا اتنين على الأقل');config.players.splice(Number(id),1);return render({preserveScroll:true})}
if(action==='begin'){multiEnabled=setupKind==='tournament';config.games=config.games.filter(g=>(multiEnabled?TOURNAMENT_GAMES:GAMES).some(x=>x[0]===g));syncSetup();let players=multiEnabled?config.players.map(s=>s.trim()).filter(Boolean):[''];if(multiEnabled&&players.length<2)return notify('اكتب اسمين على الأقل');if(setupKind==='free')config.games=[freeType];if(!config.games.length)return notify('اختاروا لعبة واحدة على الأقل');config.topics=TOPICS.map(t=>t[0]);let q=buildQueue();if(setupKind==='free'&&freeType==='guess')q=q.filter(t=>hints[t.q]);if(q.length<1)return notify('جرّب مستوى تاني');initSession(q,players);return}
if(!session)return;
if(action==='score-plus'||action==='score-minus'){session.scores[Number(id)]+=action==='score-plus'?1:-1;save();return render()}
if(action==='tie'){let options=ACTIVE_Q.filter(q=>!session.usedIds.includes(q.id));if(!options.length)options=ACTIVE_Q;let q=shuffled(options)[0];session.queue.push({q:q.id,game:'steal',player:0,golden:true});session.usedIds.push(q.id);session.finished=false;session.index=session.queue.length-1;session.revealed=false;session.answered=false;view='play';save();return render()}
if(action==='skip')return next();
if(action==='free-retry'){if(!session||session.multiplayer)return;return launchFree(freeType)}
if(action==='free-mark'){if(!session||session.multiplayer||!session.revealed)return;markFree(id==='yes');return next()}
if(action==='next')return next();
if(action==='reveal'){session.revealed=true;save();return render()}
if(action==='hint'){session.clues=Math.min(3,session.clues+1);save();return render()}
if(action==='choose'){if(session.answered)return;let q=lookup(current().q),choices=getChoices(q);session.picked=Number(id);session.answered=true;if(!session.multiplayer)markFree(choices[Number(id)]===q.answer,choices[Number(id)]);if(session.multiplayer&&choices[Number(id)]===q.answer)session.scores[current().player]+=10;save();return render()}
if(action==='award'){return record(Number(el.dataset.points||0))}
if(action==='select-level'){let level=Number(id);session.selectedLevel=level;let currentQ=lookup(current().q);let used=new Set(session.usedIds);let arr=ACTIVE_Q.filter(q=>config.topics.includes(q.topic)&&q.level===level&&(!used.has(q.id)||q.id===currentQ.id));if(arr.length){let pick=shuffled(arr)[0];session.queue[session.index].q=pick.id;session.usedIds.push(pick.id)}save();return render()}
if(action==='speed-toggle'){session.running=!session.running;if(session.running&&session.remaining===0)session.remaining=60;save();if(session.running)startClock();else clearClock();return render()}
if(action==='speed-mark'){let pts=Number(el.dataset.points);session.speedTotal++;if(!session.multiplayer){markFree(Boolean(pts),'',current().q);session.freeTurnRecorded=true}if(pts){session.speedCorrect++;if(session.multiplayer)session.scores[current().player]+=pts}else session.speedWrong++;if(session.remaining===0){session.revealed=true;save();return notify('انتهى الوقت، اضغط إنهاء الجولة')}if(!addSpeedQuestion())return notify('وصلت لنهاية الأسئلة المتاحة، أنهِ الجولة');return render()}
if(action==='speed-end')return next();
}
document.addEventListener('click',e=>{let target=e.target.closest('[data-action]');if(target)act(target.dataset.action,target.dataset.id,target)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role="button"][data-action]')){e.preventDefault();act(e.target.dataset.action,e.target.dataset.id,e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='rounds')config.rounds=Number(e.target.value);if(e.target.id==='level')config.level=Number(e.target.value);if(view==='setup')persistUI()});
document.addEventListener('input',e=>{if(view==='setup'&&e.target.matches('[data-player]')){syncSetup();persistUI()}});
document.addEventListener('toggle',e=>{if(view==='setup'&&e.target.matches('.q-setup details'))persistUI()},true);
window.addEventListener('pagehide',()=>persistUI());
let scrollSave;window.addEventListener('scroll',()=>{clearTimeout(scrollSave);scrollSave=setTimeout(persistUI,160)},{passive:true});
session=load();if(session?.running){session.running=false;save()}const restored=restoreUI();view=restored?.view||'home';render({restoreScroll:true,scrollY:restored?.scrollY||0});if(view==='setup'&&restored?.openSections?.length){document.querySelectorAll('.q-setup details').forEach((d,i)=>{d.open=restored.openSections.includes(i)})}persistUI();
